import React, { act } from "react";
import { createRoot } from "react-dom/client";
import axios from "axios";
import api from "../../lib/api";
import GoogleMerchantObservation, { validateMerchantObservation } from "./GoogleMerchantObservation";

jest.mock("../../lib/api", () => ({ __esModule: true, default: {
    get: jest.fn(), post: jest.fn(), put: jest.fn(), delete: jest.fn(), request: jest.fn(),
} }));

const scope = { ownerId: "synthetic-owner", accountId: "5052346701", merchantId: "123" };
// Generated by the actual69919f backend route -> reviewed observer.as_public_dict
// using tests.test_google_merchant_observation_routes DB/providers/call, synthetic
// crypto/transports only (2026-10-29). This is not a live Google response.
const OBSERVED = {
    scope: { owner_id: "synthetic-owner", ads_customer_id: "5052346701", merchant_id: "123" },
    products: [{ resource_name: "accounts/123/products/ar~SA~SKU1", base64_encoded_name: null,
        merchant_id: "123", legacy_local: false, language_code: "ar", feed_label: "SA", offer_id: "SKU1",
        data_source: "accounts/123/dataSources/18", archived: false, version_number: null,
        link: "https://shop.example.invalid/product?id=1", canonical_link: "https://shop.example.invalid/product",
        mobile_link: null, ads_redirect: null, item_group_id: "parent" }],
    started_at: "2026-10-29T22:07:55.423199+00:00", observed_at: "2026-10-29T22:07:55.425125+00:00",
    semantic_digest: "c9ac8b36e917a23d6312bcd56f15b6459270c49ce587720b42eaa7f2135cd996", pages_read: 1,
    source: "merchant_processed_products_v1", complete: true, atomic_snapshot: false, mapping_status: "unverified",
    store_product_mapping_verified: false, google_ads_channel_verified: false, destination_verified: false,
    category_membership_verified: false, attribution_verified: false, execution_authorized: false, provider_writes: 0,
    access_observation: { ads_customer_id: "5052346701", merchant_id: "123",
        credential_evidence_id: "google-bound-read-4249f7cdee83434f95210d85f62f135a",
        native_link_resource: "customers/5052346701/productLinks/17", local_membership: "matching_bracketing_snapshots",
        native_link_set: "matching_complete_bracketing_reads", checked_at: "2026-10-29T22:07:55.425958+00:00",
        continuous_authorization_proved: false },
};
function result() { return JSON.parse(JSON.stringify(OBSERVED)); }
let container, root;
beforeEach(() => {
    globalThis.IS_REACT_ACT_ENVIRONMENT = true;
    jest.clearAllMocks(); api.get.mockReset(); api.get.mockResolvedValue({ data: result() });
    container = document.createElement("div"); document.body.appendChild(container); root = createRoot(container);
});
afterEach(async () => { await act(async () => root.unmount()); container.remove(); });
async function render(props = {}) { await act(async () => root.render(<GoogleMerchantObservation isOwner {...scope} {...props} />)); }
function button(label = "قراءة منتجات Merchant Center") {
    return [...container.querySelectorAll("button")].find((element) => element.textContent === label);
}
async function click(label) { await act(async () => button(label).click()); }
function assertNoWrites() { for (const key of ["post", "put", "delete", "request"]) expect(api[key]).not.toHaveBeenCalled(); }

test("render is read-free; explicit click performs one fixed scoped GET with no automatic replay", async () => {
    await render(); expect(api.get).not.toHaveBeenCalled(); expect(container.textContent).toContain(scope.accountId);
    await click();
    expect(api.get).toHaveBeenCalledTimes(1);
    const [path, config] = api.get.mock.calls[0];
    expect(path).toBe("/integrations-v2/google_ads/merchant-products/observation");
    expect(config.params).toEqual({ account_id: scope.accountId, merchant_id: scope.merchantId });
    expect(config.signal).toBeInstanceOf(AbortSignal); expect(config.timeout).toBe(125000);
    expect(config._mezanAuthRetried).toBe(true); expect(config.headers).toBeUndefined();
    expect(container.textContent).toContain("SKU1"); expect(container.textContent).toContain("ar");
    expect(container.textContent).toContain("SA"); expect(container.textContent).toContain("قياسي");
    expect(container.textContent).toContain("غير مؤرشف"); expect(container.textContent).toContain("لا تثبت");
    expect(container.textContent).toContain(OBSERVED.access_observation.native_link_resource);
    expect(container.textContent).toContain(OBSERVED.products[0].data_source);
    expect(container.textContent).toContain(OBSERVED.products[0].link);
    expect(container.querySelectorAll("a, img, iframe")).toHaveLength(0);
    assertNoWrites();
});

test.each([false, undefined, "true", 1])("non-owner is hidden and makes no reads (%s)", async (isOwner) => {
    await render({ isOwner }); expect(container.textContent).toBe(""); expect(api.get).not.toHaveBeenCalled(); assertNoWrites();
});

test.each([{ ownerId: "" }, { accountId: "" }, { merchantId: "" }, { accountId: "505-234-6701" },
    { merchantId: "01" }, { accountId: 123 }, { merchantId: "9223372036854775808" }])("missing/invalid explicit selection never defaults %j", async (props) => {
    await render(props); expect(container.textContent).toContain("اختر صراحةً");
    expect(container.querySelector("button")).toBeNull(); expect(api.get).not.toHaveBeenCalled();
});

test("empty complete account result is not a claim that the store has no products", async () => {
    const value = result(); value.products = []; api.get.mockResolvedValue({ data: value });
    await render(); await click(); expect(container.textContent).toContain("لم تُرجع القراءة منتجات");
    expect(container.textContent).toContain("لا يثبت ذلك خلو متجر سلة"); assertNoWrites();
});

test.each([401, 403, 404, 409, 429, 503])("provider failures show safe messages without retry (%s)", async (status) => {
    api.get.mockRejectedValue({ message: "PRIVATE_SENTINEL", response: { status, data: { detail: "PRIVATE_SENTINEL" } } });
    await render(); await click(); expect(container.querySelector("[role='alert']")).not.toBeNull();
    expect(container.textContent).not.toContain("PRIVATE_SENTINEL"); expect(api.get).toHaveBeenCalledTimes(1); assertNoWrites();
});

test.each([{ ownerId: "other-owner" }, { accountId: "456" }, { merchantId: "789" }, { isOwner: false }])("scope changes abort and discard late response %j", async (props) => {
    let finish; api.get.mockImplementation(() => new Promise((resolve) => { finish = resolve; }));
    await render(); await click(); const signal = api.get.mock.calls[0][1].signal;
    await render(props); expect(signal.aborted).toBe(true);
    await act(async () => finish({ data: result() }));
    expect(container.textContent).not.toContain("SKU1"); expect(api.get).toHaveBeenCalledTimes(1);
});

test("old request cannot replace a new owner/account result even when transport ignores abort", async () => {
    const finish = [];
    api.get.mockImplementation(() => new Promise((resolve) => { finish.push(resolve); }));
    await render(); await click();
    await render({ ownerId: "another-owner" }); await click();
    const current = result(); current.scope.owner_id = "another-owner";
    current.products[0].offer_id = "CURRENT"; current.products[0].resource_name = "accounts/123/products/ar~SA~CURRENT";
    await act(async () => finish[1]({ data: current }));
    await act(async () => finish[0]({ data: result() }));
    expect(container.textContent).toContain("CURRENT"); expect(container.textContent).not.toContain("SKU1");
});

test("manual cancellation permits a new read but old completion cannot clear its busy state", async () => {
    const finish = [];
    api.get.mockImplementation(() => new Promise((resolve) => { finish.push(resolve); }));
    await render(); await click(); const signal = api.get.mock.calls[0][1].signal;
    await click("إلغاء القراءة"); expect(signal.aborted).toBe(true); await click();
    await act(async () => finish[0]({ data: result() }));
    expect(button().disabled).toBe(true); expect(container.textContent).not.toContain("SKU1");
    await act(async () => finish[1]({ data: result() })); expect(button().disabled).toBe(false);
});

test("unmount aborts the pending read", async () => {
    let finish; api.get.mockImplementation(() => new Promise((resolve) => { finish = resolve; }));
    await render(); await click(); const signal = api.get.mock.calls[0][1].signal;
    await act(async () => root.render(null)); expect(signal.aborted).toBe(true);
    await act(async () => finish({ data: result() })); expect(container.textContent).toBe("");
});

test("repeated click is single-flight; explicit subsequent read clears the old result", async () => {
    await render(); await click(); expect(container.textContent).toContain("SKU1");
    let finish; api.get.mockImplementation(() => new Promise((resolve) => { finish = resolve; }));
    await act(async () => { button().click(); button().click(); });
    expect(api.get).toHaveBeenCalledTimes(2); expect(container.textContent).not.toContain("SKU1");
    await act(async () => finish({ data: result() }));
});

test.each([
    ["foreign owner", (v) => { v.scope.owner_id = "foreign"; }],
    ["foreign Ads", (v) => { v.scope.ads_customer_id = "456"; }],
    ["foreign Merchant", (v) => { v.scope.merchant_id = "456"; }],
    ["incomplete", (v) => { v.complete = false; }],
    ["mapping upgraded", (v) => { v.store_product_mapping_verified = true; }],
    ["execution upgraded", (v) => { v.execution_authorized = true; }],
    ["continuous authorization", (v) => { v.access_observation.continuous_authorization_proved = true; }],
    ["foreign native link", (v) => { v.access_observation.native_link_resource = "customers/456/productLinks/17"; }],
    ["missing native evidence", (v) => { delete v.access_observation.native_link_set; }],
    ["unknown source", (v) => { v.source = "unverified"; }],
    ["no products array", (v) => { v.products = {}; }],
    ["duplicate identity", (v) => { v.products.push(v.products[0]); }],
    ["anonymous row", (v) => { v.products.push({}); }],
    ["wrong native product", (v) => { v.products[0].resource_name = "accounts/123/products/ar~QA~SKU1"; }],
    ["foreign data source", (v) => { v.products[0].data_source = "accounts/456/dataSources/18"; }],
    ["unknown legacy channel", (v) => { v.products[0].legacy_local = null; }],
    ["unknown archived state", (v) => { v.products[0].archived = "false"; }],
    ["bad timestamp", (v) => { v.observed_at = "unknown"; }],
    ["bad digest", (v) => { v.semantic_digest = "unknown"; }],
    ["oversized inventory", (v) => { v.products = Array(2001).fill(v.products[0]); }],
])("unproved response is refused in full: %s", async (_label, change) => {
    const value = result(); change(value); api.get.mockResolvedValue({ data: value });
    await render(); await click(); expect(container.querySelector("[role='alert']")).not.toBeNull();
    expect(container.textContent).not.toContain("SKU1"); expect(container.textContent).not.toContain("اكتملت قراءة");
});

test.each(["javascript:alert(1)", "https://user:password@example.invalid/product", "https://shop.example.invalid/ bad", "data:text/html,test"])('unsafe URL is refused, never rendered as a navigable link: %s', async (link) => {
    const value = result(); value.products[0].link = link; api.get.mockResolvedValue({ data: value });
    await render(); await click(); expect(container.querySelector("[role='alert']")).not.toBeNull();
    expect(container.querySelectorAll("a, iframe, img")).toHaveLength(0);
});

test("different language/feed/local identities remain separate and archived is not eligibility", async () => {
    const value = result();
    value.products.push({ ...value.products[0], language_code: "en", feed_label: "QA", legacy_local: true,
        archived: true, resource_name: "accounts/123/products/local~en~QA~SKU1" });
    api.get.mockResolvedValue({ data: value }); await render(); await click();
    expect(container.querySelectorAll("li")).toHaveLength(2);
    expect(container.textContent).toContain("محلي"); expect(container.textContent).toContain("مؤرشف");
    expect(container.textContent).toContain("لا تثبت");
});

test("paging and expanding identities are local and do not reread providers", async () => {
    const value = result(); value.products = Array.from({ length: 26 }, (_, index) => ({ ...OBSERVED.products[0],
        offer_id: `SKU-${index}`, resource_name: `accounts/123/products/ar~SA~SKU-${index}` }));
    api.get.mockResolvedValue({ data: value }); await render(); await click();
    expect(container.querySelectorAll("li")).toHaveLength(25);
    await act(async () => { container.querySelector("summary").click(); });
    await click("التالي"); expect(container.querySelectorAll("li")).toHaveLength(1); expect(container.textContent).toContain("SKU-25");
    await click("السابق"); expect(api.get).toHaveBeenCalledTimes(1); assertNoWrites();
});

test("the exact actual observer fixture preserves native identity and every explicit limit", () => {
    const value = result(); expect(validateMerchantObservation(value, scope)).toBe(value);
    expect(value.products[0].link).not.toBe(value.products[0].canonical_link);
    expect(value.mapping_status).toBe("unverified"); expect(value.google_ads_channel_verified).toBe(false);
});

test("actual existing browser API interceptor does not refresh or replay a failed manual observation", async () => {
    const actualApi = jest.requireActual("../../lib/api").default;
    const refresh = jest.spyOn(axios, "post").mockRejectedValue(new Error("UNEXPECTED_AUTH_WRITE"));
    const adapter = jest.fn(async (config) => { throw { config, response: { status: 401 }, message: "synthetic401" }; });
    api.get.mockImplementation((url, options) => actualApi.get(url, { ...options, adapter }));
    try {
        await render(); await click();
        expect(adapter).toHaveBeenCalledTimes(1); expect(refresh).not.toHaveBeenCalled();
        expect(container.querySelector("[role='alert']").textContent).toContain("الصلاحيات");
        assertNoWrites();
    } finally { refresh.mockRestore(); }
});
